// Stratified means: overall vs per-group direction check (plain JS)
function groupMeans(rows, groupKey, xKey, yKey) {
  const groups = {};
  for (const r of rows) {
    const g = r[groupKey];
    groups[g] = groups[g] || { sx: 0, sy: 0, n: 0 };
    groups[g].sx += r[xKey]; groups[g].sy += r[yKey]; groups[g].n++;
  }
  return Object.entries(groups).map(([g, s]) => ({ group: g, meanX: s.sx / s.n, meanY: s.sy / s.n }));
}
// Compare overall slope vs per-group slopes: reversals indict confounders.

