function groupMeans(rows) {
  const groups = {};
  for (const r of rows) {
    const g = r.brand;
    groups[g] = groups[g] || { sx: 0, sy: 0, n: 0 };
    groups[g].sx += r.price; groups[g].sy += r.rating; groups[g].n++;
  }
  return Object.entries(groups).map(([g, s]) => g + ':' + (s.sx / s.n).toFixed(0) + '/' + (s.sy / s.n).toFixed(2));
}
const rows = [
  { brand: 'A', price: 100, rating: 4.0 }, { brand: 'A', price: 120, rating: 4.2 },
  { brand: 'B', price: 200, rating: 4.8 }, { brand: 'B', price: 220, rating: 4.9 },
];
console.log(groupMeans(rows).join(' | '));
console.log('overall-trend-up: true (but brand explains it: B costs more AND rates higher)');

